selector_to_html = {"a[href=\"#id6\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u7b97\u5b50\u4e0e\u6269\u5c55\u70b9<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u8fd0\u884c\u65f6\u914d\u7f6e<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">RuntimeConfig</span></code> \u8bb0\u5f55\u540e\u7aef\u3001\u8bbe\u5907\u3001\u5b9e\u6570\u4e0e\u590d\u6570\u7cbe\u5ea6\u3001JAX \u7cbe\u5ea6\u3001\u77e9\u9635\u4e58\u6cd5\u7b56\u7565\u4e0e\u7ed8\u5236\u98ce\u683c\u3002\u7535\u8def\u5728\u6784\u5efa\u65f6\u6355\u83b7\u914d\u7f6e\uff0c\u5e76\u628a\u5e26\u7248\u672c\u7684\u6e05\u5355\u5d4c\u5165\u5176 IR \u4e0e\u8ba1\u5212\uff0c\u56e0\u6b64\u5206\u5e03\u5f0f\u5de5\u4f5c\u8fdb\u7a0b\u4f1a\u91cd\u5efa\u540c\u4e00\u5957\u7b56\u7565\uff0c\u800c\u4e0d\u662f\u7ee7\u627f\u53ef\u53d8\u8fdb\u7a0b\u72b6\u6001\u3002<code class=\"docutils literal notranslate\"><span class=\"pre\">runtime_config(...)</span></code> \u63d0\u4f9b\u4e0a\u4e0b\u6587\u5c40\u90e8\u7684\u4e34\u65f6\u8986\u76d6\u3002</p>", "a[href=\"#id7\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u7a33\u5b9a\u6027\u8fb9\u754c<a class=\"headerlink\" href=\"#id7\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u9519\u8bef<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><p>\u7a33\u5b9a\u7684\u751f\u547d\u5468\u671f\u7c7b\u522b\u4f4d\u4e8e <code class=\"docutils literal notranslate\"><span class=\"pre\">flagquantum.errors</span></code>\uff1a\u8bed\u4e49\u8f93\u5165\u975e\u6cd5\u65f6\u629b <code class=\"docutils literal notranslate\"><span class=\"pre\">ValidationError</span></code>\uff0c\u8ba1\u5212\u8fc7\u671f\u3001\u88ab\u7be1\u6539\u6216\u4e0d\u517c\u5bb9\u65f6\u629b <code class=\"docutils literal notranslate\"><span class=\"pre\">PlanningError</span></code>\uff0c\u6240\u8bf7\u6c42\u80fd\u529b\u4e0d\u53ef\u7528\u65f6\u629b <code class=\"docutils literal notranslate\"><span class=\"pre\">CapabilityError</span></code>\uff0c\u6267\u884c\u6216\u8bad\u7ec3\u5931\u8d25\u65f6\u629b <code class=\"docutils literal notranslate\"><span class=\"pre\">ExecutionError</span></code>\u3002\u5b83\u4eec\u90fd\u7ee7\u627f <code class=\"docutils literal notranslate\"><span class=\"pre\">FlagQuantumError</span></code> \u53ca\u5176\u517c\u5bb9\u7684 Python \u5185\u5efa\u5f02\u5e38\uff0c\u56e0\u6b64\u7a84\u8303\u56f4\u4e0e\u901a\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">except</span></code> \u90fd\u80fd\u5de5\u4f5c\u3002</p>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u63a5\u53e3\u603b\u89c8<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#id1\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u63a5\u53e3\u53c2\u8003<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>FlagQuantum \u5bf9\u5916\u53ea\u66b4\u9732\u4e00\u5957\u7ecf\u8fc7\u6574\u7406\u7684 Python \u63a5\u53e3\uff1a<code class=\"docutils literal notranslate\"><span class=\"pre\">import</span> <span class=\"pre\">flagquantum</span> <span class=\"pre\">as</span> <span class=\"pre\">fq</span></code>\u3002</p>", "a[href=\"#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6d4b\u91cf<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">fq.expectation</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">fq.probabilities</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">fq.samples</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">fq.counts</span></code> \u63cf\u8ff0\u8981\u6d4b\u91cf\u4ec0\u4e48\u3002Pauli \u4e58\u79ef\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">@</span></code>\uff0c\u54c8\u5bc6\u987f\u91cf\u6c42\u548c\u4e0e\u5b9e\u6570\u7cfb\u6570\u7528\u666e\u901a\u7b97\u672f\uff1b\u91c7\u6837\u4e0e\u8ba1\u6570\u63a5\u53d7\u8ba1\u7b97\u57fa\u6bd4\u7279\u6216\u4e00\u4e2a\u4e0d\u5e26\u6743\u91cd\u7684 Pauli \u4e58\u79ef\u3002\u7ed3\u679c\u66b4\u9732 <code class=\"docutils literal notranslate\"><span class=\"pre\">expectation()</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">expectations</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">probabilities</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">samples</span></code>\u3001<code class=\"docutils literal notranslate\"><span class=\"pre\">counts</span></code> \u4e0e <code class=\"docutils literal notranslate\"><span class=\"pre\">measurement(index_or_name)</span></code>\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
